-- ---------------------------------------------------------------------------
-- Part 0 — PREFLIGHT (aborts before any write when the world changed)
-- ---------------------------------------------------------------------------
do $$
declare
  v_count integer;
  v_batch_present integer;
  v_missing_baseline text;
begin
  select count(*) into v_count from public.restaurants;

  -- The batch was built against a 14-row baseline; after one full run there
  -- are 28. Anything else means the table changed outside this review.
  if v_count < 14 or v_count > 28 then
    raise exception 'PREFLIGHT FAIL: restaurants row count is %, expected between 14 and 28. The table changed outside this review — re-run the review before importing.', v_count;
  end if;

  -- Every known baseline restaurant must still be present.
  select string_agg(expected.name, ' | ') into v_missing_baseline
  from unnest(array['Abhiram Food Court', 'Amigos Cafe', 'Ayyappa Tiffin Room', 'Brundavana Family Restaurant', 'Chickpet Donne Biryani House', 'GITAM University Canteen', 'Hotel Halli Nanasu', 'Hotel Royal Nandhana', 'Priyanka Tiffen Center', 'Shri Manjunatha Grand Veg', 'Sri Annapoorneshwari Tiffin Center', 'Sri Ganesh Grand', 'SS Hyderabadi Biriyani Zone', 'The Biryani Shack']) as expected(name)
  where not exists (
    select 1 from public.restaurants r
    where lower(btrim(r.name)) = lower(btrim(expected.name))
  );
  if v_missing_baseline is not null then
    raise exception 'PREFLIGHT FAIL: baseline restaurants missing or renamed: %', v_missing_baseline;
  end if;

  -- How much of this batch is already applied (fixed ids)?
  select count(*) into v_batch_present from public.restaurants where id in (
    '5987ea2a-dd7b-561f-8b0a-cb6d1e614c76',
    '85807b55-1ea0-5781-8aa1-4264edec77ca',
