    '902fa33d-850b-5fb8-9a17-5c7306776e8f',
    'd644e9f7-058d-54ce-88c3-202420cccc44'
  );
  if v_batch_present = 14 then
    raise notice 'Batch 003 already fully applied — every insert below will be a no-op (idempotent re-run).';
  elsif v_batch_present > 0 then
    raise notice 'Partial prior application: %/14 rows present — only the missing rows will be inserted.', v_batch_present;
  else
    raise notice 'Fresh application: 14 proposed rows will be inserted as unverified.';
  end if;
end $$;

