  'unverified'
where not exists (
  select 1 from public.restaurants r
  where r.id = 'd644e9f7-058d-54ce-88c3-202420cccc44'
     or lower(btrim(r.name)) = lower(btrim('Palav Ramu Hotel'))
);

-- ---------------------------------------------------------------------------
-- Part 2 — POSTFLIGHT (verification queries; they READ, they never write)
-- ---------------------------------------------------------------------------

-- 2.1 Final row count (fresh run -> 28; idempotent re-run -> 28).
select count(*) as final_row_count from public.restaurants;

-- 2.2 Every batch row must exist exactly once, still unverified, with
--     untouched aggregates and NULL verification state. Any row missing
--     here was skipped by its guard — investigate before proceeding.
select r.name, r.verification_status, r.review_count, r.community_rating,
       r.address_verified, r.coordinates_verified, r.hours_verified, r.photos_verified,
       r.last_verified_at, r.latitude, r.longitude
from public.restaurants r
where r.id in (
  '5987ea2a-dd7b-561f-8b0a-cb6d1e614c76',
  '85807b55-1ea0-5781-8aa1-4264edec77ca',
  '17330e95-8470-5d90-aff0-e9a6bf3c1bdb',
  '6cda358f-f756-58e7-aa62-6b6fd808fb8f',
  'b5359a3e-dead-5481-b469-d8d0e1dd80be',
  'a28b5aa3-70d6-5ff1-b36f-faf3fd1cd1ac',
  'c7e99d61-c536-571f-81ac-c8807ec914d9',
  'a6caa179-490d-55ba-8acc-608225d624a4',
  '18d3bc43-f148-5b3e-980c-e9f63ebfe6f1',
  'f93d78ab-ac75-5477-85d0-ca800a7cd33f',
  'c5fcb7c8-a971-569c-a162-d6bebbf9e5fa',
  '966f2829-6584-5315-bef3-46800053a84e',
  '902fa33d-850b-5fb8-9a17-5c7306776e8f',
  'd644e9f7-058d-54ce-88c3-202420cccc44'
)
order by r.name;
-- Expected: exactly 14 rows, verification_status 'unverified', review_count 0,
--           community_rating NULL, all four *_verified NULL, last_verified_at NULL.

-- 2.3 No duplicate normalized names anywhere in the table (must return 0 rows).
select lower(btrim(name)) as normalized_name, count(*) as copies
from public.restaurants
group by 1 having count(*) > 1;

-- 2.4 Community aggregates must be untouched by this batch (must return 0 rows).
select name from public.restaurants
where id in (
  '5987ea2a-dd7b-561f-8b0a-cb6d1e614c76',
  '85807b55-1ea0-5781-8aa1-4264edec77ca',
  '17330e95-8470-5d90-aff0-e9a6bf3c1bdb',
  '6cda358f-f756-58e7-aa62-6b6fd808fb8f',
  'b5359a3e-dead-5481-b469-d8d0e1dd80be',
  'a28b5aa3-70d6-5ff1-b36f-faf3fd1cd1ac',
  'c7e99d61-c536-571f-81ac-c8807ec914d9',
  'a6caa179-490d-55ba-8acc-608225d624a4',
  '18d3bc43-f148-5b3e-980c-e9f63ebfe6f1',
  'f93d78ab-ac75-5477-85d0-ca800a7cd33f',
  'c5fcb7c8-a971-569c-a162-d6bebbf9e5fa',
  '966f2829-6584-5315-bef3-46800053a84e',
  '902fa33d-850b-5fb8-9a17-5c7306776e8f',
  'd644e9f7-058d-54ce-88c3-202420cccc44'
)
  and (review_count <> 0 or community_rating is not null);

-- 2.5 Proximity report — all pairs within 0.2 km, for human eyeballing only.
--     Known advisory pairs expected here: Bindushree<->Abhis; (held rows
--     Krishnamoorthy / Five Star Kohli Hut are NOT in this table).
select a.name as name_a, b.name as name_b,
       round((6371 * acos(least(1, greatest(-1,
         sin(radians(a.latitude)) * sin(radians(b.latitude)) +
         cos(radians(a.latitude)) * cos(radians(b.latitude)) *
         cos(radians(b.longitude) - radians(a.longitude))
       ))))::numeric / 1000, 2) as km_apart
from public.restaurants a
join public.restaurants b
  on a.id < b.id and a.latitude is not null and b.latitude is not null
where (6371 * acos(least(1, greatest(-1,
  sin(radians(a.latitude)) * sin(radians(b.latitude)) +
  cos(radians(a.latitude)) * cos(radians(b.latitude)) *
  cos(radians(b.longitude) - radians(a.longitude))
)))) <= 0.2
order by km_apart;

